theorem eqOn_periodize_of_support_le_half {T : ℝ} (hT : 0 < T) {h : ℝ → ℂ}
    (hsupp : ∀ x : ℝ, x ∉ Set.Icc 0 (T / 2) → h x = 0) :
    Set.EqOn (periodize T h) h (Set.Ioo (-(T / 2)) T)

theorem toAngle_bijOn :
    Set.BijOn toAngle Set.univ
      {g : ℝ → ℂ | ContDiff ℝ ∞ g ∧ Function.Periodic g (2 * Real.pi)}

theorem iteratedDerivWithin_eq_zero_of_iteratedFDerivWithin_eq_zero {s : Set ℝ} {f : ℝ → ℂ}
    {x : ℝ} {n : ℕ} (h : iteratedFDerivWithin ℝ n f s x = 0) :
    iteratedDerivWithin n f s x = 0

theorem iteratedFDerivWithin_mul_eq_zero_of_flat {E : Type*}
    [NormedAddCommGroup E] [NormedSpace ℝ E]
    {a h : E → ℂ} {s : Set E} {x : E}
    (ha : ContDiffOn ℝ ∞ a s) (hh : ContDiffOn ℝ ∞ h s) (hs : UniqueDiffOn ℝ s) (hx : x ∈ s)
    (hflat : ∀ i : ℕ, iteratedFDerivWithin ℝ i h s x = 0) (n : ℕ) :
    iteratedFDerivWithin ℝ n (fun y => a y * h y) s x = 0

theorem gaussConv_ofReal {s : ℝ} (hs : 0 < s) {a : ℝ → ℂ}
    (ha : IsRapidlyDecaying a) (x : ℝ) :
    gaussConv s a (x : ℂ) = gaussConvReal s a x

theorem integrable_gaussConv_integrand {s : ℝ} (hs : 0 < s) {a : ℝ → ℂ}
    (ha : IsRapidlyDecaying a) (w : ℂ) :
    Integrable (fun t : ℝ => gaussKernel s (w - (t : ℂ)) * a t)

theorem iteratedDeriv_gaussConvReal {s : ℝ} (hs : 0 < s) {a : ℝ → ℂ}
    (ha : IsRapidlyDecaying a) (k : ℕ) :
    iteratedDeriv k (gaussConvReal s a) = gaussConvReal s (iteratedDeriv k a)

theorem tendsto_testFn_of_forall_eventually {ι : Type*} {l : Filter ι} {u : ι → TestFn}
    {f : TestFn}
    (h : ∀ (N : ℕ) (ε : ℝ), 0 < ε →
      ∀ᶠ i in l, ∀ j ≤ N, ∀ θ : ℝ, ‖angleDeriv j (u i) θ - angleDeriv j f θ‖ < ε) :
    Filter.Tendsto u l (𝓝 f)

theorem interior_strip (τ : ℂ) :
    interior (strip τ) =
      { z : ℂ | min 0 τ.im < z.im ∧ z.im < max 0 τ.im }

theorem toAngle_splitUpper_of_mem {f : TestFn} (h : IsEndpointFlat f) {θ : ℝ}
    (hθ : θ ∈ Set.Icc 0 Real.pi) :
    toAngle (splitUpper f h) θ = toAngle f θ

theorem AnalyticTestFn.evalSphere_congr {F G : AnalyticTestFn}
    (h : Set.EqOn F.toFun G.toFun Oexterior) {p : OnePoint ℂ} (hp : p ∈ Oset) :
    F.evalSphere p = G.evalSphere p

theorem AnalyticTestFn.iteratedDeriv_boundary_eq_zero (F : AnalyticTestFn) (n : ℕ) {θ : ℝ}
    (hθ : (Circle.exp θ : ℂ) = 1 ∨ (Circle.exp θ : ℂ) = -1) :
    iteratedDeriv n (fun θ : ℝ => F.toFun (Circle.exp θ)) θ = 0

theorem norm_iteratedDeriv_inv_le_of_ge (m : ℕ) {c y : ℝ}
    (hc : 0 < c) (hcy : c ≤ y) :
    ‖iteratedDeriv m (Inv.inv : ℝ → ℝ) y‖ ≤ (Nat.factorial m : ℝ) / c ^ (m + 1)

theorem betaBoostVal_circleExp_pi (d : ℕ) (F : AnalyticTestFn) {τ : ℂ}
    (hτ : τ ∈ strip (Complex.I * Real.pi)) :
    betaBoostVal d τ F (Circle.exp Real.pi) = 0

theorem betaBoost_apply_circleExp (d : ℕ) (F : AnalyticTestFn) {τ : ℂ}
    (hτ : τ ∈ strip (Complex.I * Real.pi)) {θ : ℝ} (hθ : θ ∈ Set.Icc 0 Real.pi) :
    betaBoost d τ F (Circle.exp θ) = betaBoostVal d τ F (Circle.exp θ)

theorem toAngle_betaBoost (d : ℕ) (F : AnalyticTestFn) {τ : ℂ}
    (hτ : τ ∈ strip (Complex.I * Real.pi)) :
    toAngle (betaBoost d τ F) = periodize (2 * Real.pi) (betaBoostCut d τ F)

theorem angleDeriv_betaBoost_of_mem (d : ℕ) (F : AnalyticTestFn) (j : ℕ) {τ : ℂ}
    (hτ : τ ∈ strip (Complex.I * Real.pi)) {θ : ℝ} (hθ : θ ∈ Set.Icc 0 Real.pi) :
    angleDeriv j (betaBoost d τ F) θ = betaBoostSlice d F j (τ, θ)

theorem angleDeriv_betaBoost_of_notMem (d : ℕ) (F : AnalyticTestFn) (j : ℕ) {τ : ℂ}
    (hτ : τ ∈ strip (Complex.I * Real.pi)) {θ : ℝ}
    (hθ : θ ∈ Set.Ioo Real.pi (2 * Real.pi)) :
    angleDeriv j (betaBoost d τ F) θ = 0

theorem betaBoostSliceDot_eq_zero_of_endpoint (d : ℕ) (F : AnalyticTestFn) (j : ℕ) {τ : ℂ}
    (hτ : τ ∈ interior (strip (Complex.I * Real.pi))) {θ : ℝ}
    (hθ : θ = 0 ∨ θ = Real.pi) :
    betaBoostSliceDot d F j (τ, θ) = 0

theorem deriv_betaBoostSlice (d : ℕ) (F : AnalyticTestFn) (j : ℕ) {τ : ℂ}
    (hτ : τ ∈ interior (strip (Complex.I * Real.pi))) {θ : ℝ}
    (hθ : θ ∈ Set.Icc 0 Real.pi) :
    deriv (fun σ : ℂ => betaBoostSlice d F j (σ, θ)) τ = betaBoostSliceDot d F j (τ, θ)

theorem hasDerivAt_betaBoostSlice (d : ℕ) (F : AnalyticTestFn) (j : ℕ) {τ : ℂ}
    (hτ : τ ∈ interior (strip (Complex.I * Real.pi))) {θ : ℝ}
    (hθ : θ ∈ Set.Icc 0 Real.pi) :
    HasDerivAt (fun σ : ℂ => betaBoostSlice d F j (σ, θ))
      (betaBoostSliceDot d F j (τ, θ)) τ

theorem angleDeriv_betaBoostDeriv_of_mem (d : ℕ) (F : AnalyticTestFn) (j : ℕ) {τ : ℂ}
    (hτ : τ ∈ strip (Complex.I * Real.pi)) {θ : ℝ} (hθ : θ ∈ Set.Icc 0 Real.pi) :
    angleDeriv j (betaBoostDeriv d τ F) θ = betaBoostSliceDot d F j (τ, θ)

theorem angleDeriv_betaBoostDeriv_of_notMem (d : ℕ) (F : AnalyticTestFn) (j : ℕ) {τ : ℂ}
    (hτ : τ ∈ strip (Complex.I * Real.pi)) {θ : ℝ}
    (hθ : θ ∈ Set.Ioo Real.pi (2 * Real.pi)) :
    angleDeriv j (betaBoostDeriv d τ F) θ = 0

theorem contDiffOn_betaBoostSliceDot_angle (d : ℕ) (F : AnalyticTestFn) {τ : ℂ}
    (hτ : τ ∈ strip (Complex.I * Real.pi)) :
    ContDiffOn ℝ ∞ (fun θ : ℝ => betaBoostSliceDot d F 0 (τ, θ)) (Set.Icc 0 Real.pi)

theorem sliceDeriv_betaBoostSliceDot (d : ℕ) (F : AnalyticTestFn) (j : ℕ) {p : ℂ × ℝ}
    (hp : p ∈ stripUpper) :
    sliceDeriv stripUpper j (betaBoostSliceDot d F 0) p = betaBoostSliceDot d F j p

theorem toAngle_betaBoostDeriv (d : ℕ) (F : AnalyticTestFn) {τ : ℂ}
    (hτ : τ ∈ strip (Complex.I * Real.pi)) :
    toAngle (betaBoostDeriv d τ F) = periodize (2 * Real.pi) (betaBoostDerivCut d τ F)

theorem hasTestFnDerivAt_betaBoost (d : ℕ) (F : AnalyticTestFn) {τ : ℂ}
    (hτ : τ ∈ interior (strip (Complex.I * Real.pi))) :
    HasTestFnDerivAt (fun σ : ℂ => betaBoost d σ F) (betaBoostDeriv d τ F) τ

theorem beta_boostMat_betaBoost (d : ℕ) (t : ℝ) {τ : ℂ}
    (hτ : τ ∈ strip (Complex.I * Real.pi)) (F : AnalyticTestFn) :
    beta d (boostMat t) (betaBoost d τ F) = betaBoost d (τ + (t : ℂ)) F

theorem analyticAt_stripApprox {s : ℝ} (hs : 0 < s) {a : ℝ → ℂ}
    (ha : IsRapidlyDecaying a) {z : ℂ} (hz : z ∉ cutSegment) :
    AnalyticAt ℂ (stripApprox s a) z

theorem contDiffOn_stripApprox {s : ℝ} (hs : 0 < s) {a : ℝ → ℂ}
    (ha : IsRapidlyDecaying a) :
    ContDiffOn ℝ ∞ (stripApprox s a) Oexterior

theorem differentiableOn_stripApprox {s : ℝ} (hs : 0 < s) {a : ℝ → ℂ}
    (ha : IsRapidlyDecaying a) :
    DifferentiableOn ℂ (stripApprox s a) OexteriorInterior

theorem stripApprox_of_notMem_cutSegment {s : ℝ} {a : ℝ → ℂ} {z : ℂ}
    (hz : z ∉ cutSegment) :
    stripApprox s a z = gaussConv s a (boostCoord z) / z

theorem tendsto_stripApprox {s : ℝ} (hs : 0 < s) {a : ℝ → ℂ}
    (ha : IsRapidlyDecaying a) :
    Filter.Tendsto (stripApprox s a) (Filter.cocompact ℂ) (nhds 0)

theorem lemma_3_4_density_lower :
    { f : TestFn | SuppLower f } ⊆
      closure { g : TestFn | ∃ F : AnalyticTestFn, xRestrictLower F = g }

theorem tendsto_starTestFn {u : ℕ → TestFn} {f : TestFn}
    (h : Tendsto u atTop (nhds f)) :
    Tendsto (fun n => starTestFn (u n)) atTop (nhds (starTestFn f))

theorem disjointSupport_of_suppUpper_of_tsupport_subset_lowerArc {f h' : TestFn}
    (hf : SuppUpper f) (hh' : tsupport (h' : Circle → ℂ) ⊆ lowerArc) :
    DisjointSupport f h'

@[simp] theorem multiSmearMultilinear_apply (W : WightmanStruct TF 𝓓 𝓕) {k : ℕ}
    (φs : Fin k → 𝓕) (Φ : 𝓓) (f : Fin k → TF) :
    W.multiSmearMultilinear φs Φ f = W.multiSmear φs Φ f

theorem vtildeVal_unique (W : WightmanData G TF 𝓓 𝓕)
    (hreg : W.toWightmanStruct.ActsRegularly) {τ : ℂ} {Φ Ψ Ψ' : 𝓓}
    (h : W.VtildeVal τ Φ Ψ) (h' : W.VtildeVal τ Φ Ψ') : Ψ = Ψ'

theorem vtildeDom_mirror_iff {W : WightmanData Mob TestFn 𝓓 𝓕}
    (hW : W.IsWightmanCFT) (τ : ℂ) (Φ : 𝓓) :
    W.VtildeDom (-τ) Φ ↔ W.VtildeDom τ (W.U (Mob.rot Real.pi) Φ)
